      "第三段將個案事實逐一涵攝，特別檢查法定代理人或適當之人陪同、陳述意見、辯護／輔佐、收容或其他人身自由保障。",
      "末段逐問作成明確結論，並交代後續處遇、移送、紀錄塗銷或救濟等效果。"
